<?php defined('PREVENT_DIRECT_ACCESS') OR exit('No direct script access allowed'); ?>
<div class="row between"><h1>Reservations</h1><a class="btn" href="<?= e(site_url('admin/walkin')) ?>">+ New walk-in</a></div>
<form method="get" action="<?= e(site_url('admin/reservations')) ?>" class="row" style="margin:12px 0"><input name="q" placeholder="Search reference or guest name" value="<?= e($search) ?>" maxlength="60" style="max-width:300px">
<select name="status" style="max-width:200px"><option value="">All statuses</option><?php foreach (['pending_payment','confirmed','checked_in','checked_out','cancelled','expired'] as $s): ?><option value="<?= e($s) ?>"<?= $status === $s ? ' selected' : '' ?>><?= e(str_replace('_', ' ', $s)) ?></option><?php endforeach; ?></select><button class="btn btn-ink" type="submit">Filter</button></form>
<div class="card scroll"><table class="table"><thead><tr><th>Ref</th><th>Guest</th><th>Room</th><th>Stay</th><th>Check-in</th><th>Total</th><th>Status</th></tr></thead><tbody>
<?php foreach ($rows as $b): ?><tr><td><a href="<?= e(site_url('admin/reservations/' . $b['booking_ref'])) ?>"><b><?= e($b['booking_ref']) ?></b></a></td><td><?= e($b['guest_name']) ?></td><td><?= e($b['room_no']) ?> <span class="mute small"><?= e($b['type_name']) ?></span></td><td><?= e(stay_label($b)) ?></td><td><?= e(fmt_dt($b['start_at'], 'j M · g:i A')) ?></td><td><?= e(money($b['total'])) ?></td><td><span class="pill <?= e(status_class($b['status'])) ?>"><?= e(str_replace('_', ' ', $b['status'])) ?></span></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="7" class="center mute">No reservations found.</td></tr><?php endif; ?></tbody></table></div>
